<?php
declare(strict_types=1);
require_once __DIR__.'/db.php';
function wow_auth_audit_source(string $value):string{$v=strtolower(trim($value));return match($v){'passenger_app','passenger_mobile_app'=>'passenger_app','passenger_website','passenger_web'=>'passenger_website','driver_app','driver_mobile_app'=>'driver_app','driver_website','driver_web'=>'driver_website','admin_website','admin_web'=>'admin_website',default=>'unknown'};}
function wow_auth_audit_log(array $event):void{try{$type=strtolower(trim((string)($event['eventType']??'unknown')));$status=strtolower(trim((string)($event['status']??'pending')));$source=wow_auth_audit_source((string)($event['sourcePlatform']??''));$uid=trim((string)($event['userId']??''));$email=strtolower(trim((string)($event['email']??'')));$reference=trim((string)($event['relatedRequestId']??''));$bucket=(string)floor(time()/10);$eventId=hash('sha256',implode('|',[$uid?:$email,$type,$status,$source,$reference,$bucket]));$agent=substr((string)($_SERVER['HTTP_USER_AGENT']??'unknown'),0,180);$device=preg_match('/android|iphone|ipad|mobile/i',$agent)?'Mobile':'Web browser';wow_set_doc('authAuditLogs',$eventId,['eventId'=>$eventId,'userId'=>$uid,'email'=>$email,'role'=>strtolower(trim((string)($event['role']??'unknown'))),'eventType'=>$type,'status'=>$status,'authProvider'=>strtolower(trim((string)($event['authProvider']??'password'))),'sourcePlatform'=>$source,'createdAt'=>wow_now(),'deviceType'=>$device,'browserOrApp'=>$agent,'failureReasonCode'=>substr((string)($event['failureReasonCode']??''),0,100),'isSuspicious'=>(bool)($event['isSuspicious']??false),'riskReason'=>substr((string)($event['riskReason']??''),0,180),'relatedRequestId'=>$reference,'reviewed'=>false],true);}catch(Throwable$e){error_log('Auth audit write failed: '.$e->getMessage());}}
